    QCOMPARE(independent, KisPageStoreWriteOperationResult::Succeeded);
    QCOMPARE(calls, 1); QCOMPARE(independentCalls, 1);
    QCOMPARE(store->sessionStats().activeCpuWritePages, qsizetype(0));
